        int before = hangingPlayers.size();
        ObjectIterator iterator = hangingPlayers.object2IntEntrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry entry = (Map.Entry)iterator.next();
            int newTTL = (Integer)entry.getValue() - 1;
            if (newTTL <= 0) {
